"""Running work on behalf of an external caller.

Two shapes, because Kasal has two:

* the BLOCKING ask, over the chat path — fits inside a tool-call timeout;
* ASYNC HANDLES for crews — start returns a run id immediately, and the caller
  polls status/result or cancels.

The chat path (``execution_type="agent"``) runs a single agent in-process via
``Agent.kickoff_async`` — no subprocess, no crew, sub-second. That makes it the
one Kasal execution shape that fits inside an ordinary tool-call timeout, which
is why it is the first thing exposed: it exercises transport, identity and group
scoping end to end without needing any async-handle machinery.

Crew runs take minutes; the run-level budget work contemplates up to an hour.
There is deliberately NO blocking crew call — one would look fine against a
three-task crew in testing and time out in production, and having it available
is how it ends up used. ``start_run`` returns a handle and returns it fast.

Everything that reaches Databricks runs on the CALLER's token (OBO). A caller
with no token gets ``auth_required`` before a run is created, rather than a run
that starts and fails inside an agent with a permissions error.

No new execution logic lives here. Everything goes through
``services/execution/`` exactly as a browser-initiated run does, which is what
makes execution history, traces, logs and the OTel bridge apply for free.
"""

import logging
import uuid
from dataclasses import dataclass
from datetime import datetime
from typing import Any, Dict, Optional
from uuid import UUID

from src.models.execution_status import ExecutionStatus
from src.schemas.execution import CrewConfig
from src.services.external.identity import ExternalCaller
from src.services.external.state import (
    ExternalTaskState,
    is_terminal,
    to_external_state,
)

logger = logging.getLogger(__name__)

#: Agent used for a bare question. Deliberately generic: `ask_kasal` answers
#: from the model plus whatever the workspace's configuration provides, and is
#: not a substitute for a published crew with a declared purpose.
_ASK_AGENT_KEY = "kasal_assistant"


@dataclass(frozen=True)
class InvocationResult:
    """What an adapter renders back to its caller.

    Protocol-neutral: the MCP adapter turns this into a tool result, the A2A
    adapter into a Task with Parts. Neither re-derives the state.
    """

    run_id: str
    state: ExternalTaskState
    output: Optional[str] = None
    error: Optional[str] = None

    def as_dict(self) -> Dict[str, Any]:
        payload: Dict[str, Any] = {"run_id": self.run_id, "state": self.state.value}
        if self.output is not None:
            payload["output"] = self.output
        if self.error is not None:
            payload["error"] = self.error
        return payload


def _build_ask_config(
    question: str, model: Optional[str], capabilities: Optional[list] = None
) -> CrewConfig:
    """A one-agent, one-task config for the chat path.

    The question becomes the task description, which is what the light agent
    kicks off on. Nothing is generated by an LLM to get here — an `ask` must not
    pay for a crew-generation round-trip before it can answer.

    ``capabilities`` grounds the agent in what this workspace can actually do.
    Without it the agent is asked to answer ON BEHALF OF a workspace it has been
    told nothing about, and it fills the gap: asked "what is Kasal", an early
    version confidently described "a secure workspace environment for
    collaborative AI research", which is not what Kasal is. An agent with no
    grounding does not answer "I don't know" by default — it has to be given
    something to be faithful to, and told to decline when it has not.
    """
    if capabilities:
        published = "\n".join(f"- {c.name}: {c.description}" for c in capabilities)
        workspace_context = (
            "This workspace has published these capabilities for external "
            f"callers:\n{published}\n\n"
            "A caller can start any of them by name."
        )
    else:
        workspace_context = (
            "This workspace has published no capabilities for external callers."
        )

    return CrewConfig(
        agents_yaml={
            _ASK_AGENT_KEY: {
                "role": "Kasal Assistant",
                "goal": "Answer the question accurately and concisely.",
                "backstory": (
                    "You answer questions on behalf of a Kasal workspace for an "
                    "external agent that is calling in over MCP or A2A.\n\n"
                    f"{workspace_context}\n\n"
                    "You are precise and you do not speculate. In particular, do "
                    "NOT invent facts about this workspace, its data, its "
                    "purpose, or what Kasal is — you know only what is stated "
                    "above. If the question asks about any of that and the "
                    "answer is not above, say plainly that you do not have that "
                    "information. General questions you can answer from your own "
                    "knowledge, answer normally."
                ),
            }
        },
        tasks_yaml={
            "answer": {
                "description": question,
                "expected_output": "A direct answer to the question.",
                "agent": _ASK_AGENT_KEY,
            }
        },
        inputs={},
        model=model,
        execution_type="agent",
    )


async def ask(
    caller: ExternalCaller,
    question: str,
    model: Optional[str] = None,
    session: Any = None,
) -> InvocationResult:
    """Answer a question over the chat path, blocking until it is done.

    Runs as the caller's resolved group. The execution is recorded like any
    other, stamped with the caller's origin, so "who asked this, over which
    protocol, and what did it cost" is answerable from the audit trail rather
    than being reconstructed later.
    """
    if not question or not question.strip():
        raise ValueError("question must not be empty")

    # Imported here, not at module scope: services/execution/ pulls in the
    # engine, and the EIL is imported by routers that must stay cheap to load.
    from src.services.execution.service import ExecutionService
    from src.services.execution.status import ExecutionStatusService

    execution_id = str(uuid.uuid4())
    group_context = caller.group_context

    await ExecutionStatusService.create_execution(
        execution_data={
            "job_id": execution_id,
            "status": ExecutionStatus.PENDING.value,
            "run_name": f"ask via {caller.protocol}",
            "created_at": datetime.now(),
            # The origin tag. One field, written at the only point every
            # external invocation passes through.
            "inputs": {"external_origin": caller.origin, "question": question},
        },
        group_context=group_context,
        session=session,
    )

    # What this workspace actually offers, so the agent answers from fact rather
    # than filling the gap. Group-scoped like every other capability read.
    capabilities = []
    try:
        from src.services.external.publication import PublicationService

        capabilities = await PublicationService(session).list_capabilities(caller)
    except Exception as exc:  # noqa: BLE001
        # Grounding is an enrichment; never fail an ask because it could not be
        # loaded.
        logger.debug("[external] capability grounding skipped: %s", exc)

    logger.info(
        "[external] %s ask started run=%s group=%s",
        caller.protocol,
        execution_id,
        caller.group_ids,
    )

    try:
        result = await ExecutionService.run_crew_execution(
            execution_id=execution_id,
            config=_build_ask_config(question, model, capabilities),
            execution_type="agent",
            group_context=group_context,
            session=session,
        )
    except Exception as exc:  # noqa: BLE001 — an external caller gets an answer
        # The caller is another agent, not a browser: an unhandled exception
        # crossing the protocol boundary becomes an opaque transport error with
        # no run id to follow up on. Report the failure as a result instead.
        logger.exception("[external] ask failed for run %s", execution_id)
        return InvocationResult(
            run_id=execution_id, state=ExternalTaskState.FAILED, error=str(exc)
        )

    answer = _to_result(execution_id, result)

    # The chat path returns {"execution_id", "status"} and NOTHING else: it
    # writes the answer to the execution row and returns a receipt. So a
    # successful ask arrives here with output=None, as_dict() drops the empty
    # field, and the caller receives {"run_id", "state": "completed"} — a tool
    # whose entire contract is "get a direct answer" answering with no answer.
    #
    # Re-read the row rather than changing what the chat path returns: that path
    # is shared with the UI, and this seam is the one place that needs the value
    # inline.
    if answer.output is None and is_terminal(answer.state):
        stored = await run_status(caller, execution_id, session=session)
        if stored is not None and stored.output is not None:
            answer = InvocationResult(
                run_id=execution_id,
                state=answer.state,
                output=stored.output,
                error=answer.error,
            )

    return answer


def _to_result(execution_id: str, raw: Any) -> InvocationResult:
    """Normalise whatever the execution path returned into an InvocationResult.

    The chat path returns a dict; be defensive about its exact shape, because
    this is the boundary where a change in the execution layer would otherwise
    surface to an external caller as a crash.
    """
    if not isinstance(raw, dict):
        return InvocationResult(
            run_id=execution_id,
            state=ExternalTaskState.COMPLETED,
            output=str(raw) if raw is not None else None,
        )

    state = to_external_state(raw.get("status"))
    output = raw.get("result") or raw.get("output") or raw.get("message")
    if isinstance(output, dict):
        output = output.get("raw") or output.get("content") or str(output)

    # An error is only reported alongside a FAILING state. The execution row
    # stores the terminal MESSAGE in the column surfaced as `error`, so a
    # perfectly successful run carries "Light agent execution completed" there —
    # and a non-null error next to `completed` reads as a failure to any A2A or
    # MCP client, which is a contradiction they cannot resolve.
    error = raw.get("error")
    if state not in (ExternalTaskState.FAILED, ExternalTaskState.REJECTED):
        error = None

    return InvocationResult(
        run_id=execution_id,
        state=state,
        output=str(output) if output is not None else None,
        error=error,
    )


# ---------------------------------------------------------------------------
# Async handles — the shape crews need.
# ---------------------------------------------------------------------------


async def start_run(
    caller: ExternalCaller,
    publication: Any,
    inputs: Optional[Dict[str, Any]] = None,
    session: Any = None,
) -> InvocationResult:
    """Start a published crew OR flow and return a handle immediately.

    Never waits for the run. The caller polls :func:`run_status` (or streams) —
    see the module docstring for why a blocking variant does not exist.

    ``publication`` is one the caller has ALREADY been authorised for by
    ``PublicationService.resolve_capability``; this function does not re-resolve
    it, so there is exactly one place that decides whether a caller may reach a
    given capability.
    """
    # OBO: the run executes as the caller when they presented a token, which
    # in production they always have. Without one the Databricks auth chain
    # applies, exactly as for a UI-initiated run.
    caller.obo_token()

    entity_type = getattr(publication, "entity_type", "crew") or "crew"
    # entity_id on the model; crew_id only on the older schema objects. Reading
    # `.crew_id` off a Publication raises AttributeError — the column was
    # renamed when flows became publishable, and only the CLASS kept an alias.
    entity_id = str(
        getattr(publication, "entity_id", None)
        or getattr(publication, "crew_id", "")
        or ""
    )
    if not entity_id:
        raise ValueError("Publication carries no entity id")

    # Flows run on their own path with their own service. Branching HERE, rather
    # than threading entity_type down into a crew config, keeps the difference
    # where it belongs: an external caller invokes a capability and has no reason
    # to know which engine path runs it.
    if entity_type == "flow":
        return await _start_flow(caller, publication, entity_id, inputs, session)

    from src.services.catalog.crews import CrewService
    from src.services.execution.service import ExecutionService

    crew_service = CrewService(session)
    # entity_id is persisted as a string on the publication (it is an external
    # identifier there), but Crew.id is a UUID column — asyncpg rejects a str
    # with "'str' object has no attribute 'hex'".
    try:
        crew_key = UUID(entity_id)
    except (ValueError, AttributeError, TypeError):
        crew_key = entity_id
    crew = await crew_service.get(crew_key)
    if crew is None:
        raise ValueError(f"Published crew {entity_id} no longer exists")

    agents_yaml, tasks_yaml = await _crew_to_yaml(crew, session)
    if not agents_yaml or not tasks_yaml:
        raise ValueError(
            f"Published crew {publication.external_name!r} has no agents or tasks"
        )

    config = CrewConfig(
        agents_yaml=agents_yaml,
        tasks_yaml=tasks_yaml,
        inputs={**(inputs or {}), "external_origin": caller.origin},
        execution_type="crew",
    )

    service = ExecutionService(session)
    created = await service.create_execution(
        config=config, group_context=caller.group_context
    )
    run_id = (created or {}).get("execution_id", "")

    logger.info(
        "[external] %s started crew %s as run=%s (group=%s)",
        caller.protocol,
        publication.external_name,
        run_id,
        caller.group_ids,
    )
    return InvocationResult(
        run_id=run_id, state=to_external_state((created or {}).get("status"))
    )


async def run_status(
    caller: ExternalCaller, run_id: str, session: Any = None
) -> Optional[InvocationResult]:
    """The current state of a run, or None if this caller may not see it.

    None for both "no such run" and "another tenant's run" — the caller must not
    be able to tell those apart, or run ids become an oracle for other
    workspaces' activity.
    """
    from src.services.execution.service import ExecutionService

    service = ExecutionService(session)
    raw = await service.get_execution_status(run_id, caller.group_ids)
    if raw is None:
        return None
    return _to_result(run_id, raw)


async def run_result(
    caller: ExternalCaller, run_id: str, session: Any = None
) -> Optional[InvocationResult]:
    """A finished run's output. Same group scoping as :func:`run_status`.

    Returns the run whatever its state: a caller asking for the result of a run
    that is still working gets ``working`` and no output, which is a better
    answer than an error it has to special-case.
    """
    return await run_status(caller, run_id, session=session)


async def cancel_run(
    caller: ExternalCaller, run_id: str, session: Any = None
) -> Optional[InvocationResult]:
    """Stop a run. None if the caller may not see it."""
    from src.services.execution.service import ExecutionService

    service = ExecutionService(session)

    # Authorise through the same group-scoped read as everything else BEFORE
    # stopping anything — the stop path itself takes a bare execution id.
    current = await service.get_execution_status(run_id, caller.group_ids)
    if current is None:
        return None

    await service.stop_execution(
        execution_id=run_id,
        stop_type="user_requested",
        reason=f"cancelled by {caller.origin}",
        requested_by=caller.identifier,
        db=session,
    )
    return InvocationResult(run_id=run_id, state=ExternalTaskState.CANCELED)


async def _crew_to_yaml(crew: Any, session: Any) -> tuple:
    """A saved crew -> the agents_yaml/tasks_yaml the engine takes.

    Resolved from ``agent_ids``/``task_ids`` rather than from the canvas
    ``nodes``: nodes are presentation data (positions, edges, UI state) and a
    crew can be perfectly valid with none, while the id lists are what the crew
    actually IS.

    The browser builds this same projection client-side before calling
    /executions. Doing it here rather than in the adapters means an
    externally-started run is assembled the same way whichever protocol asked —
    a second copy is a second way for an external run to differ from a UI one.
    """
    from src.services.catalog.agents import AgentService
    from src.services.catalog.tasks import TaskService

    agent_service = AgentService(session)
    task_service = TaskService(session)

    agents_yaml: Dict[str, Any] = {}
    agent_key_by_id: Dict[str, str] = {}
    for agent_id in getattr(crew, "agent_ids", None) or []:
        agent = await agent_service.get(str(agent_id))
        if agent is None:
            continue
        key = agent.name or agent.role or str(agent_id)
        agent_key_by_id[str(agent_id)] = key
        agents_yaml[key] = {
            "role": agent.role,
            "goal": agent.goal,
            "backstory": agent.backstory,
            "llm": agent.llm,
            "tools": getattr(agent, "tools", None) or [],
        }

    tasks_yaml: Dict[str, Any] = {}
    for task_id in getattr(crew, "task_ids", None) or []:
        task = await task_service.get(str(task_id))
        if task is None:
            continue
        key = task.name or str(task_id)
        entry: Dict[str, Any] = {
            "description": task.description,
            "expected_output": task.expected_output,
            "tools": getattr(task, "tools", None) or [],
        }
        assigned = agent_key_by_id.get(str(getattr(task, "agent_id", "") or ""))
        if assigned:
            entry["agent"] = assigned
        tasks_yaml[key] = entry

    return agents_yaml, tasks_yaml


async def _start_flow(
    caller: ExternalCaller,
    publication: Any,
    flow_id: str,
    inputs: Optional[Dict[str, Any]],
    session: Any,
) -> InvocationResult:
    """Start a published FLOW and return a handle.

    The flow service owns its own job id, run naming and status row, so this
    delegates rather than reassembling any of it — the same reasoning that keeps
    the crew branch going through ExecutionService. An externally-started run
    must be indistinguishable from a UI-started one everywhere except its origin
    tag, or the traces, logs and history stop lining up.
    """
    from src.services.flow_builder.execution_service import KasalFlowService

    run_id = str(uuid.uuid4())
    result = await KasalFlowService(session).run_flow(
        flow_id=flow_id,
        job_id=run_id,
        run_name=f"{publication.external_name} via {caller.protocol}",
        config={**(inputs or {}), "external_origin": caller.origin},
        group_context=caller.group_context,
        user_token=caller.obo_token(),
    )

    logger.info(
        "[external] %s started flow %s as run=%s (group=%s)",
        caller.protocol,
        publication.external_name,
        run_id,
        caller.group_ids,
    )
    returned = (result or {}).get("job_id") or (result or {}).get("execution_id")
    return InvocationResult(
        run_id=str(returned or run_id),
        state=to_external_state((result or {}).get("status")),
    )
